12	/**
13	 * Records the locality of a newly built owner: {@code "local"} when this owner's
14	 * city is the single most common city among the owners that already exist at the
15	 * moment this owner is created, {@code "remote"} otherwise. A city only counts as
16	 * most common when it has strictly more owners than every other city (a tie means
17	 * there is no single most common city, so the result is {@code "remote"}). The new
18	 * owner is not yet saved, so it is excluded from the tally. Runs after the city has
19	 * been normalised so it compares against each city's canonical spelling.
20	 */
21	public class AssignLocality {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
24	        String city = owner.getCity();
25	        Map<String, Long> cityCounts = ownerRepository.findAll().stream()
26	                .map(Owner::getCity)
27	                .filter(Objects::nonNull)
28	                .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));
29	
30	        long max = cityCounts.values().stream().mapToLong(Long::longValue).max().orElse(0L);
31	        long numberWithMax = cityCounts.values().stream().filter(count -> count == max).count();
32	
33	        boolean local = max > 0 && numberWithMax == 1 && city != null
34	                && cityCounts.getOrDefault(city, 0L) == max;
35	        owner.setLocality(local ? "local" : "remote");
36	    }
37	}
